import 'package:flutter/foundation.dart';
import '../../data/repositories/project_finance_repository.dart';
import '../../domain/models/project_finance.dart';
class ProjectFinanceProvider extends ChangeNotifier { final _repository=ProjectFinanceRepository(); ProjectFinance? _finance; bool _isLoading=false; String? _error; ProjectFinance? get finance=>_finance; bool get isLoading=>_isLoading; String? get error=>_error; Future<void> load(String projectId) async { _isLoading=true; _error=null; notifyListeners(); try { _finance=await _repository.getByProjectId(projectId); if(_finance==null){final n=DateTime.now(); _finance=ProjectFinance(id:'',projectId:projectId,createdAt:n,updatedAt:n);} } catch(e){_error=e.toString();} finally{_isLoading=false; notifyListeners();} } Future<void> save({required String projectId,required double plannedAmount,required double receivedAmount,required double expensesAmount}) async { _isLoading=true; _error=null; notifyListeners(); try {final n=DateTime.now(); _finance=await _repository.save(ProjectFinance(id:_finance?.id??'',projectId:projectId,plannedAmount:plannedAmount,receivedAmount:receivedAmount,expensesAmount:expensesAmount,createdAt:_finance?.createdAt??n,updatedAt:n));}catch(e){_error=e.toString();}finally{_isLoading=false;notifyListeners();}} }
